class MimeType:
    def __init__(self, name, mime_type, icon):
        self.name = name
        self.mime_type = mime_type
        self.icon = icon

def get_file_mime_type(path):
    _, ext = os.path.splitext(path)
    ext = ext.lower()

    if ext == '.xyz':
        return 'model/obj'

    if ext == '.xml':
        return 'text/xml'

    mimetypes.init()

    return mimetypes.guess_type(path)[0]

def format_size(size):
    formatter = re.compile('([0-9]+)\.([0-9]+)')
    result = formatter.match(str(size))

    if result:
        whole = result.group(1)
        fraction = result.group(2)

        if fraction:
            if fraction[0] == '0' and fraction[1] == '0':
                return whole
            else:
                return whole + fraction[0:2]
        else:
            return whole

    return str(size)

def escape(text):
    text = html.escape(text)

    return text

def encode(text):
    text = text.encode('utf-8')

    return text

